<script setup>
import {ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue';import katex from 'katex';
const readStorage=key=>{try{return JSON.parse(localStorage.getItem(key))}catch{return null}};
const legacy=readStorage('basis-v1');
const initialProjects=readStorage('basis-projects-v2')|| (legacy?[{id:'imported-task',name:'Моя задача',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),data:legacy}]:[]);
const projects=ref(initialProjects),activeId=ref(initialProjects[0]?.id||null),projectMenu=ref(null),projectDialog=ref(null),projectName=ref(''),projectError=ref(''),storageError=ref(''),nameInput=ref(null),switching=ref(false);
const saved=initialProjects[0]?.data;
const currentProject=computed(()=>projects.value.find(p=>p.id===activeId.value));
const sortedProjects=computed(()=>[...projects.value].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)));
function writeProjects(){try{localStorage.setItem('basis-projects-v2',JSON.stringify(projects.value));localStorage.removeItem('basis-v1');storageError.value=''}catch{storageError.value='Не удалось сохранить изменения в браузере. Возможно, хранилище заполнено.'}}
function projectSnapshot(){return JSON.parse(JSON.stringify({n:n.value,m:m.value,c:c.value,rows:rows.value,direction:direction.value,result:result.value,previous:previous.value,solvedData:solvedData.value,step:step.value,iteration:iteration.value,tab:tab.value,view:['editor','iterations','result'].includes(page.value)?page.value:(currentProject.value?.data?.view||'editor')}))}
function persistProject(){if(switching.value||!currentProject.value)return;currentProject.value.data=projectSnapshot();currentProject.value.updatedAt=new Date().toISOString();writeProjects()}
function goProjects(){if(busy.value)return;persistProject();page.value='projects';projectMenu.value=null}
async function openProject(project){if(busy.value)return;persistProject();switching.value=true;activeId.value=project.id;const d=project.data||{};n.value=d.n||2;m.value=d.m||3;c.value=d.c||['',''];rows.value=d.rows||Array.from({length:3},()=>({a:['',''],op:'≤',b:''}));direction.value=d.direction||'max';result.value=d.result||null;previous.value=d.previous||null;solvedData.value=d.solvedData||null;step.value=d.step||0;iteration.value=d.iteration||0;tab.value=d.tab||'Решение';page.value=d.result&&['result','iterations'].includes(d.view)?d.view:'editor';error.value='';panel.value=false;selected.value=null;compare.value=false;training.value='';projectMenu.value=null;await nextTick();switching.value=false;persistProject()}
async function askProject(action,project=null){projectMenu.value=null;projectDialog.value={action,id:project?.id};projectName.value=project?.name||`Пример ${projects.value.length+1}`;projectError.value='';await nextTick();nameInput.value?.focus();nameInput.value?.select()}
function submitProject(){const name=projectName.value.trim();if(!name){projectError.value='Введите название проекта.';return}if(name.length>80){projectError.value='Название должно быть не длиннее 80 символов.';return}if(projectDialog.value.action==='rename'){const p=projects.value.find(p=>p.id===projectDialog.value.id);if(p){p.name=name;p.updatedAt=new Date().toISOString();writeProjects()}}else{const now=new Date().toISOString();const p={id:crypto.randomUUID(),name,createdAt:now,updatedAt:now,data:{n:2,m:3,c:['',''],rows:Array.from({length:3},()=>({a:['',''],op:'≤',b:''})),direction:'max',step:0,view:'editor'}};projects.value.push(p);writeProjects();openProject(p)}projectDialog.value=null}
function deleteProject(){const id=projectDialog.value.id;projects.value=projects.value.filter(p=>p.id!==id);if(activeId.value===id)activeId.value=null;writeProjects();projectDialog.value=null}
function formatDate(value){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value))}
function projectStatus(p){return !p.data?.result?'Черновик':p.data.result.status==='optimal'?'Решено':'Расчёт завершён'}
function closeOverlays(e){if(e.key==='Escape'){projectDialog.value=null;projectMenu.value=null;showAbout.value=false}}

const page=ref('home'),step=ref(saved?.step||0),n=ref(saved?.n||2),m=ref(saved?.m||3),c=ref(saved?.c||['','']),rows=ref(saved?.rows||Array.from({length:3},()=>({a:['',''],op:'≤',b:''}))),direction=ref(saved?.direction||'max');
const result=ref(saved?.result||null),previous=ref(saved?.previous||null),solvedData=ref(saved?.solvedData||null),iteration=ref(saved?.iteration||0),tab=ref(saved?.tab||'Решение'),panel=ref(false),selected=ref(null),expanded=ref(false),mode=ref('auto'),fraction=ref(false),error=ref(''),busy=ref(false),loadingText=ref('Вычисляем…'),auto=ref(true),vertex=ref(0),training=ref(''),compare=ref(false),showAbout=ref(false);
const steps=['Размерность','Целевая функция','Ограничения','Проверка'];const vertices=[[130,355],[335,300],[440,170],[270,90]];let timer,worker;
const tex=(s)=>katex.renderToString(String(s),{throwOnError:false});
const num=v=>{if(Math.abs(v)<1e-10)return '0';if(!fraction.value)return String(Number(v.toFixed(6)));let best=[Math.round(v),1],err=Math.abs(v-best[0]);for(let d=1;d<=1000;d++){let p=Math.round(v*d),e=Math.abs(v-p/d);if(e<err){best=[p,d];err=e}if(e<1e-9)break}return best[1]===1?String(best[0]):`\\frac{${best[0]}}{${best[1]}}`};
const snapshot=computed(()=>result.value?.snapshots[iteration.value]);
const isNumber=v=>String(v).trim()!==''&&Number.isFinite(Number(String(v).replace(',','.')));
const norm=v=>Number(String(v).replace(',','.'));
const data=()=>({c:c.value.map(norm),direction:direction.value,rows:rows.value.map(r=>({a:r.a.map(norm),op:r.op,b:norm(r.b)}))});
const signature=computed(()=>JSON.stringify({c:c.value,rows:rows.value,direction:direction.value}));const stale=computed(()=>result.value&&solvedData.value&&JSON.stringify(data())!==JSON.stringify(solvedData.value));
watch([n,m],()=>{n.value=Math.max(1,Math.min(20,Number(n.value)||1));m.value=Math.max(1,Math.min(20,Number(m.value)||1));c.value=Array.from({length:n.value},(_,j)=>c.value[j]??'');rows.value=Array.from({length:m.value},(_,i)=>({a:Array.from({length:n.value},(_,j)=>rows.value[i]?.a[j]??''),op:rows.value[i]?.op||'≤',b:rows.value[i]?.b??''}));});
watch([signature,n,m,result,previous,solvedData,step,iteration,tab,page],persistProject,{deep:true,flush:'post'});
function start(){goProjects()}
function next(){error.value='';if(step.value===1&&!c.value.every(isNumber)){error.value='Заполните все коэффициенты целевой функции.';return}if(step.value===2&&!rows.value.every(r=>r.a.every(isNumber)&&isNumber(r.b))){error.value='Заполните коэффициенты и правые части. Пустые поля можно заполнить нулями.';return}step.value=Math.min(3,step.value+1)}
function zeros(){c.value=c.value.map(v=>v===''?'0':v);rows.value=rows.value.map(r=>({...r,a:r.a.map(v=>v===''?'0':v),b:r.b===''?'0':r.b}));}
function paste(e,i,j){const values=e.clipboardData.getData('text');if(!/[\t\n]/.test(values))return;e.preventDefault();values.trim().split(/\r?\n/).forEach((line,k)=>line.split('\t').forEach((v,l)=>{if(rows.value[i+k]&&j+l<n.value)rows.value[i+k].a[j+l]=v.trim()}));}
function solve(view){error.value='';if(!c.value.every(isNumber)||!rows.value.every(r=>r.a.every(isNumber)&&isNumber(r.b))){error.value='Есть незаполненные или некорректные значения. Вернитесь к вводу.';return}busy.value=true;loadingText.value='Загружаем Python для первого расчёта…';const input=data();if(!worker)worker=new Worker('/worker.js',{type:'module'});worker.onmessage=e=>{if(e.data.loading)return;if(e.data.error){busy.value=false;error.value='Не удалось выполнить расчёт: '+e.data.error;return}previous.value=result.value?{...result.value,source:solvedData.value}:previous.value;result.value=e.data.result;solvedData.value=input;iteration.value=0;page.value=view;busy.value=false;panel.value=false;selected.value=null;tab.value='Решение';};worker.onerror=()=>{busy.value=false;error.value='Не удалось загрузить вычислительный модуль. Обновите страницу и повторите расчёт.';worker.terminate();worker=null};worker.postMessage(input);}
function move(k){iteration.value=Math.max(0,Math.min(result.value.snapshots.length-1,iteration.value+k));selected.value=null;training.value='';}
function cell(i,j){const s=snapshot.value;if(mode.value==='learn'&&s.enter!==null){training.value=i===s.leave&&j===s.enter?'Верно. Минимальное допустимое отношение определяет разрешающую строку.':`Допустимый выбор: строка ${s.leave+1}, столбец ${s.enter+1}. Выбираем улучшающий столбец и минимальное неотрицательное отношение.`;}selected.value={i,j};panel.value=true;expanded.value=false;}
const formula=computed(()=>{const s=snapshot.value,q=selected.value;if(!s||!q)return '';const prev=result.value.snapshots[iteration.value-1];if(!prev||prev.phase!==s.phase||prev.leave===null||prev.table.length!==s.table.length)return `${s.names[q.j]||'b'}=${num(s.table[q.i][q.j])}`;let i=q.i,j=q.j,r=prev.leave,k=prev.enter,p=prev.table[r][k];if(i===r)return `${num(prev.table[i][j])}\\div ${num(p)}=${num(s.table[i][j])}`;return `${num(prev.table[i][j])}-(${num(prev.table[i][k])})\\cdot\\frac{${num(prev.table[r][j])}}{${num(p)}}=${num(s.table[i][j])}`;});
const statusText=computed(()=>({optimal:'Оптимальное решение найдено',infeasible:'Ограничения несовместны',unbounded:'Целевая функция не ограничена',limit:'Достигнут предел итераций'}[result.value?.status]));
function print(){window.print()}
onMounted(()=>{writeProjects();window.addEventListener('keydown',closeOverlays);timer=setInterval(()=>{if(auto.value)vertex.value=(vertex.value+1)%vertices.length},2200)});onUnmounted(()=>{window.removeEventListener('keydown',closeOverlays);clearInterval(timer);worker?.terminate()});
</script>
<template>
<div class="site">
<header class="nav"><button class="brand wordmark" :disabled="busy" @click="persistProject();page='home'" aria-label="Базис — на главную">базис<span class="brand-dot">.</span></button><nav><button @click="showAbout=true">О методе <span>↗</span></button><template v-if="page!=='home'"><span class="nav-sep"></span><button :disabled="busy" @click="goProjects">Мои решения <span>↗</span></button></template></nav><span class="edition">ВЫЧИСЛИТЕЛЬНАЯ МАТЕМАТИКА / 01</span></header>
<p v-if="storageError" class="storage-warning" role="alert">{{storageError}}</p>
<main v-if="page==='home'" class="landing">
<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="tiny-dot"></span> ПРОСТРАНСТВО РЕШЕНИЙ</p><h1>У сложной задачи<br>есть <em>точка</em><br><em>решения.</em></h1><p class="hero-description">От системы ограничений до оптимума.<br>Симплекс-метод, который можно понять —<br>и объяснить на каждом шаге.</p><div class="hero-actions"><button class="primary" @click="start">Начать решение <span>↗</span></button></div></div>
<div class="geometry"><div class="figure-top"><span>01 / ГЕОМЕТРИЯ МЕТОДА</span><span>2 ПЕРЕМЕННЫЕ</span></div><svg viewBox="0 0 600 470" role="img" aria-label="Иллюстрация движения по вершинам допустимой области к оптимуму"><defs><pattern id="dots" width="16" height="16" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".8" fill="#b7b7b7"/></pattern><pattern id="hatch" width="7" height="7" patternUnits="userSpaceOnUse" patternTransform="rotate(30)"><line y2="7" stroke="#d9d9d9" stroke-width="1"/></pattern></defs><rect x="65" y="40" width="480" height="365" fill="url(#dots)"/><path d="M80 400H555M95 420V35" class="axis"/><path d="M550 396l6 4-6 4M91 41l4-6 4 6" class="axis"/><path d="M130 355L335 300L440 170L270 90L130 200Z" fill="url(#hatch)" stroke="#aaa" stroke-width="1"/><path d="M130 355L335 300L440 170L270 90" fill="none" stroke="#222" stroke-width="1.4" stroke-dasharray="4 5"/><line x1="180" y1="40" x2="525" y2="325" class="objective"/><text x="408" y="110" class="svg-small">f(x) → max</text><text x="555" y="425" class="svg-small">x₁</text><text x="68" y="38" class="svg-small">x₂</text><text x="61" y="424" class="svg-small">0</text><text x="195" y="259" class="area-label">ДОПУСТИМАЯ</text><text x="195" y="277" class="area-label">ОБЛАСТЬ</text><circle v-for="(v,i) in vertices" :cx="v[0]" :cy="v[1]" r="4" fill="white" stroke="#222"/><g class="moving-point" :style="{transform:`translate(${vertices[vertex][0]}px,${vertices[vertex][1]}px)`}"><circle r="17" fill="white" stroke="#111" stroke-dasharray="2 3"/><circle r="6" fill="#111"/><path d="M16 -17h35" stroke="#111"/><text x="55" y="-14" class="svg-small">{{vertex===3?'оптимум':'шаг '+(vertex+1)}}</text></g></svg><div class="figure-controls"><button class="round" :aria-label="auto?'Остановить анимацию':'Запустить анимацию'" @click="auto=!auto">{{auto?'Ⅱ':'▷'}}</button><span>{{auto?'Движение к оптимуму':'Ручной просмотр'}}</span><div class="figure-pages"><button v-for="(_,i) in vertices" :aria-label="'Вершина '+(i+1)" :class="{active:vertex===i}" @click="auto=false;vertex=i">0{{i+1}}</button></div></div></div></section>
<section class="intro-strip"><div class="strip-title">Математика.<br><span>Без чёрного ящика.</span></div><article><span class="index">01</span><h3>Задайте условия</h3><p>Коэффициенты, функция, ограничения.<br>Всё по порядку, ничего лишнего.</p></article><article><span class="index">02</span><h3>Проследите путь</h3><p>Каждая итерация и выбор базиса.<br>Столько подробностей, сколько нужно.</p></article><article><span class="index">03</span><h3>Проверьте ответ</h3><p>Результат, подстановка и невязки.<br>Сохраните итог в PDF.</p></article></section><footer><span>БАЗИС © 2026</span><span>СИМПЛЕКС-МЕТОД / ИСКУССТВЕННЫЙ БАЗИС</span><span>ПОНЯТЬ. РЕШИТЬ. ПРОВЕРИТЬ.</span></footer>
</main>
<main v-else-if="page==='projects'" class="workspace projects-page" @click="projectMenu=null">
<div class="projects-heading"><div><p class="eyebrow">ВАШЕ ПРОСТРАНСТВО / ИСТОРИЯ РЕШЕНИЙ</p><h2>Мои решения<span class="project-count">{{projects.length.toString().padStart(2,'0')}}</span></h2><p class="subheading">Каждая задача — отдельный проект. Продолжайте с того места, где остановились.</p></div><span class="saved">Сохранено в этом браузере</span></div>
<div class="projects-grid"><article v-for="p in sortedProjects" :key="p.id" class="project-card"><div class="project-card-top"><span class="eyebrow">{{projectStatus(p)}}</span><div class="project-menu-wrap"><button class="project-more" :aria-label="'Меню проекта '+p.name" :aria-expanded="projectMenu===p.id" @click.stop="projectMenu=projectMenu===p.id?null:p.id">···</button><div v-if="projectMenu===p.id" class="project-menu"><button @click.stop="askProject('rename',p)">Переименовать <span>↗</span></button><button @click.stop="askProject('delete',p)">Удалить <span>×</span></button></div></div></div><button class="project-title" :title="p.name" @click="openProject(p)">{{p.name}}</button><p class="project-dimensions">{{p.data?.n||2}} перем. <span>·</span> {{p.data?.m||3}} огр.</p><div class="project-card-bottom"><time :datetime="p.updatedAt">{{formatDate(p.updatedAt)}}</time><button class="project-arrow" :aria-label="'Открыть проект '+p.name" @click="openProject(p)">↗</button></div></article>
<button class="project-add" @click="askProject('create')" aria-label="Создать проект"><span class="plus-symbol">+</span><span>Новое решение</span></button></div>
<p v-if="!projects.length" class="projects-empty">Нажмите «+», задайте название и введите условия своей задачи.</p><div class="projects-footer"><span>Ваши задачи. Ваш ход решения.</span><span>АВТОСОХРАНЕНИЕ ВКЛЮЧЕНО</span></div>
</main>
<main v-else-if="page==='editor'" class="workspace editor">
<div class="workspace-heading"><p class="eyebrow">{{currentProject?.name}} / ЛИНЕЙНОЕ ПРОГРАММИРОВАНИЕ</p><span class="saved"><i></i> Сохраняется в браузере</span></div><div class="stepper"><button v-for="(s,i) in steps" :class="{current:step===i,done:step>i}" @click="i<step&&(step=i)"><span>{{step>i?'✓':'0'+(i+1)}}</span>{{s}}</button></div>
<section class="editor-content"><p class="eyebrow">ШАГ 0{{step+1}} / 04</p><h2>{{['С чего начнём?','Что оптимизируем?','Зададим границы.','Всё готово к решению.'][step]}}</h2><p class="subheading">{{['Укажите количество переменных и ограничений вашей задачи.','Введите коэффициенты целевой функции и выберите направление.','Введите коэффициенты, знаки ограничений и правые части.','Проверьте постановку и выберите, как пройти решение.'][step]}}</p>
<div v-if="step===0" class="dimension-grid"><label>Количество переменных <span>n</span><div class="number-control"><button @click="n=Math.max(1,n-1)" aria-label="Уменьшить число переменных">−</button><input type="number" min="1" max="20" v-model.number="n" aria-label="Количество переменных"><button @click="n=Math.min(20,n+1)" aria-label="Увеличить число переменных">+</button></div><small>От 1 до 20 переменных</small></label><label>Количество ограничений <span>m</span><div class="number-control"><button @click="m=Math.max(1,m-1)" aria-label="Уменьшить число ограничений">−</button><input type="number" min="1" max="20" v-model.number="m" aria-label="Количество ограничений"><button @click="m=Math.min(20,m+1)" aria-label="Увеличить число ограничений">+</button></div><small>Не считая условий неотрицательности</small></label></div>
<div v-if="step===1" class="input-section"><div class="section-toolbar"><span v-html="tex('f(x)=c^Tx')"></span><div class="segmented"><button :class="{active:direction==='max'}" @click="direction='max'">Максимум</button><button :class="{active:direction==='min'}" @click="direction='min'">Минимум</button></div></div><div class="table-scroll"><table class="input-table"><thead><tr><th v-for="j in n" v-html="tex(`x_{${j}}`)"></th></tr></thead><tbody><tr><td v-for="(_,j) in c"><input v-model="c[j]" inputmode="decimal" placeholder="—" :aria-label="'Коэффициент функции x'+(j+1)"></td></tr></tbody></table></div></div>
<div v-if="step===2" class="input-section"><div class="section-toolbar"><span>{{m}} ограничения · {{n}} переменные</span><button class="text-button" @click="zeros">Заполнить пустые нулями ↘</button></div><div class="table-scroll"><table class="input-table"><thead><tr><th class="row-label">№</th><th v-for="j in n" v-html="tex(`x_{${j}}`)"></th><th>Знак</th><th class="sticky" v-html="tex('b')"></th></tr></thead><tbody><tr v-for="(r,i) in rows"><th class="row-label">0{{i+1}}</th><td v-for="(_,j) in r.a"><input v-model="r.a[j]" placeholder="—" inputmode="decimal" :aria-label="`Ограничение ${i+1}, x${j+1}`" @paste="paste($event,i,j)"></td><td><select v-model="r.op" :aria-label="'Знак ограничения '+(i+1)"><option>≤</option><option>=</option><option>≥</option></select></td><td class="sticky"><input v-model="r.b" placeholder="—" inputmode="decimal" :aria-label="'Правая часть '+(i+1)"></td></tr></tbody></table></div><p class="input-hint">Tab — следующая ячейка · Поддерживается вставка диапазона из таблицы · <span v-html="tex('x_i\\geq 0')"></span></p></div>
<div v-if="step===3" class="review-grid"><section class="problem-preview"><p class="eyebrow">ВАША ПОСТАНОВКА</p><div class="math-line" v-html="tex(c.map((v,j)=>`(${v||'?'})x_{${j+1}}`).join('+')+'\\to\\mathrm{'+direction+'}')"></div><div v-for="r in rows" class="math-line" v-html="tex(r.a.map((v,j)=>`(${v||'?'})x_{${j+1}}`).join('+')+({'≤':'\\leq','≥':'\\geq','=':'='}[r.op])+r.b)"></div><div class="math-line" v-html="tex('x_i\\geq0,\\quad i=1,\\ldots,'+n)"></div><button class="text-button" @click="step=1">Изменить данные ↗</button></section><section class="launch-options"><div><h3>Выберите свой путь</h3><p>Результат одинаковый. Глубина погружения — ваша.</p></div><button class="launch-card" :disabled="busy" @click="solve('iterations')"><span class="launch-icon">↳</span><span><strong>Пройти по шагам</strong><small>Итерации, выбор базиса и разбор вычислений</small></span><span>↗</span></button><button class="launch-card" :disabled="busy" @click="solve('result')"><span class="launch-icon">◎</span><span><strong>Сразу к результату</strong><small>Ответ, проверка ограничений и погрешности</small></span><span>↗</span></button><p v-if="busy" class="loading" role="status">{{loadingText}}</p></section></div>
<p v-if="error" class="error" role="alert">{{error}}</p>
</section><div class="editor-bottom"><button class="text-button" @click="step===0?goProjects():step--">← {{step===0?'К проектам':'Назад'}}</button><span>Данные остаются только в вашем браузере</span><button v-if="step<3" class="primary" @click="next">Продолжить <span>→</span></button><span v-else class="editor-final-spacer"></span></div>
</main>
<main v-else class="workspace solution"><div class="solution-top"><div><p class="eyebrow">{{currentProject?.name}} / {{solvedData?.c.length}} ПЕРЕМЕННЫЕ</p><h2>{{page==='iterations'?'Путь к решению.':result.status==='optimal'?'Точка найдена.':'Разберём результат.'}}</h2></div><div class="solution-actions"><button class="secondary" @click="page=page==='iterations'?'result':'iterations'">{{page==='iterations'?'К результату ↗':'Ход решения ↗'}}</button><button class="secondary" @click="page='editor';step=1">Изменить задачу</button><button class="primary" @click="print">Скачать PDF ↓</button></div></div><p v-if="stale" class="notice">Исходные данные изменены. Здесь показано предыдущее решение. Запустите новый расчёт для сравнения.</p>
<template v-if="page==='iterations'&&snapshot"><div class="iteration-toolbar"><span class="eyebrow">ЭТАП {{snapshot.phase}} / {{snapshot.phase===1?'ИСКУССТВЕННЫЙ БАЗИС':'ИСХОДНАЯ ФУНКЦИЯ'}}</span><div class="segmented"><button :class="{active:mode==='auto'}" @click="mode='auto'">Авторазбор</button><button :class="{active:mode==='learn'}" @click="mode='learn'">Учебный</button></div><button class="secondary" @click="fraction=!fraction">{{fraction?'Дроби':'Десятичные'}} ⇄</button><button class="secondary" @click="panel=!panel">Пояснения {{panel?'−':'+'}}</button></div><div class="table-with-panel" :class="{open:panel}"><section class="table-area"><div class="table-caption"><h3>Таблица {{iteration+1}} <span>/ {{result.snapshots.length}}</span></h3><span>{{snapshot.enter===null?'Критерий оптимальности выполнен':mode==='learn'?'Выберите разрешающий элемент':'Разрешающий элемент выделен'}}</span></div><div class="table-scroll"><table class="simplex-table"><thead><tr><th>Базис</th><th v-for="name in snapshot.names" v-html="tex(name)"></th><th class="sticky" v-html="tex('b')"></th></tr></thead><tbody><tr v-for="(row,i) in snapshot.table"><th v-html="tex(snapshot.names[snapshot.basis[i]])"></th><td v-for="(v,j) in row" :class="{pivot:mode==='auto'&&i===snapshot.leave&&j===snapshot.enter,focuscol:mode==='auto'&&j===snapshot.enter,sticky:j===row.length-1}"><button @click="cell(i,j)" v-html="tex(num(v))"></button></td></tr><tr class="reduced"><th v-html="tex('\\Delta_j')"></th><td v-for="v in snapshot.reduced" v-html="tex(num(v))"></td><td class="sticky" v-html="tex(num(snapshot.value))"></td></tr></tbody></table></div><p class="input-hint">Нажмите на число, чтобы увидеть его вычисление.</p><p v-if="training" class="notice">{{training}}</p><details class="canonical"><summary>Приведение к канонической форме</summary><p>Для ≤ добавляем неотрицательную дополнительную переменную; для ≥ вычитаем её. При отрицательной правой части меняем знак строки. Для начального базиса при необходимости добавляем искусственные переменные и минимизируем их сумму на этапе I.</p><div v-for="(r,i) in solvedData.rows" class="math-line" v-html="tex(r.a.map((v,j)=>`(${v})x_{${j+1}}`).join('+')+(r.op==='≤'?`+s_{${i+1}}`:r.op==='≥'?`-s_{${i+1}}`:'')+'='+r.b)"></div></details></section><aside v-if="panel" class="explanation"><div class="aside-heading"><span class="eyebrow">ВНУТРИ ВЫЧИСЛЕНИЯ</span><button @click="panel=false" aria-label="Закрыть пояснения">×</button></div><h3>{{selected?'Как получено число':'Выбор следующего базиса'}}</h3><template v-if="selected"><p>Строка {{selected.i+1}} · столбец {{selected.j+1}}</p><div class="formula-box" v-html="tex(formula)"></div><button class="text-button" @click="expanded=!expanded">{{expanded?'Скрыть':'Разобрать'}} преобразование строки {{expanded?'−':'+'}}</button><p v-if="expanded">Разрешающую строку делим на разрешающий элемент. Из остальных строк вычитаем новую разрешающую строку, умноженную на коэффициент в разрешающем столбце. Для начальной таблицы значения берутся из приведённой системы.</p></template><template v-else><p v-if="snapshot.enter===null">Все оценки неположительны: дальнейшее улучшение на данном этапе невозможно.</p><p v-else-if="snapshot.leave===null">В улучшающем столбце нет положительных коэффициентов. Функция не ограничена в выбранном направлении.</p><template v-else><p>Используем правило Бланда: первый столбец с положительной оценкой.</p><div class="formula-box" v-html="tex(snapshot.names[snapshot.enter]+'\\to\\text{базис}')"></div><p>Разрешающая строка — по минимальному неотрицательному отношению.</p><p v-for="(v,i) in snapshot.ratios">Строка {{i+1}}: <span v-html="tex(v===null?'\\text{—}':num(v))"></span></p></template></template></aside></div><div class="iteration-bottom"><button class="secondary" :disabled="iteration===0" @click="move(-1)">← Назад</button><input type="range" min="0" :max="result.snapshots.length-1" :value="iteration" @input="iteration=+$event.target.value;selected=null" aria-label="Выбор таблицы"><span>{{iteration+1}} / {{result.snapshots.length}}</span><button class="primary" :disabled="iteration===result.snapshots.length-1" @click="move(1)">Следующая →</button></div></template>
<template v-if="page==='result'"><div class="result-status"><span class="tiny-dot"></span>{{statusText}}</div><div v-if="result.status==='optimal'" class="result-tabs"><button v-for="t in ['Решение','Проверка','Погрешности']" :class="{active:tab===t}" @click="tab=t">{{t}}</button><button v-if="previous" class="compare-button" @click="compare=!compare">Сравнить с предыдущим {{compare?'−':'+'}}</button></div><section v-if="result.status==='optimal'" class="result-content"><div v-if="tab==='Решение'" class="answer-layout"><div class="objective-answer"><p class="eyebrow">{{solvedData.direction==='max'?'МАКСИМУМ':'МИНИМУМ'}} ФУНКЦИИ</p><div v-html="tex('f(x^*)='+num(result.value))"></div></div><div class="variables"><div v-for="(v,i) in result.x" v-html="tex(`x_{${i+1}}^*=${num(v)}`)"></div></div></div><div v-if="tab==='Проверка'"><p class="subheading">Подставляем найденные значения в исходные ограничения.</p><table class="check-table"><thead><tr><th>Ограничение</th><th>Левая часть</th><th>Условие</th><th>Правая часть</th><th>Проверка</th></tr></thead><tbody><tr v-for="(r,i) in result.checks"><td>{{i+1}}</td><td>{{r.lhs.toPrecision(8)}}</td><td>{{solvedData.rows[i].op}}</td><td>{{r.rhs}}</td><td>{{r.violation<1e-8?'✓ Выполнено':'Нарушено'}}</td></tr></tbody></table></div><div v-if="tab==='Погрешности'" class="error-report"><p class="eyebrow">МАКСИМАЛЬНОЕ НАРУШЕНИЕ ОГРАНИЧЕНИЙ</p><h2>{{result.error.toExponential(3)}}</h2><p>Абсолютная невязка для равенств и величина нарушения для неравенств. Проверяется также неотрицательность переменных. Допуск алгоритма: 10⁻⁹.</p><p>Эта оценка проверяет допустимость; она не является гарантированной границей ошибки найденного оптимума.</p></div><section v-if="compare&&previous" class="comparison"><h3>Предыдущий расчёт</h3><p>{{previous.status==='optimal'?'Значение функции: '+previous.value:'Статус: '+previous.status}}</p><p v-if="previous.x" v-html="tex('x=('+previous.x.map(num).join(';')+')')"></p><small>Предыдущая постановка сохранена вместе с решением.</small></section></section><section v-else class="empty-state"><p>{{result.status==='infeasible'?'Не существует точки, удовлетворяющей всем ограничениям.':result.status==='unbounded'?'Допустимая область позволяет улучшать функцию без конечного предела.':'Вычисление остановлено после 500 итераций на этапе.'}}</p><button class="primary" @click="page='iterations';iteration=result.snapshots.length-1">Подробный разбор ↗</button></section></template>
<section class="print-report"><h1>Базис — {{currentProject?.name}}</h1><p>{{statusText}}</p><p v-html="tex(solvedData.c.map((v,j)=>`(${v})x_{${j+1}}`).join('+')+'\\to\\mathrm{'+solvedData.direction+'}')"></p><p v-for="r in solvedData.rows" v-html="tex(r.a.map((v,j)=>`(${v})x_{${j+1}}`).join('+')+({'≤':'\\leq','≥':'\\geq','=':'='}[r.op])+r.b)"></p><p v-html="tex('x_i\\geq0')"></p><template v-if="result.status==='optimal'"><p v-html="tex('x^*=('+result.x.map(num).join(';')+'),\\quad f^*='+num(result.value))"></p><p v-for="(r,i) in result.checks">Ограничение {{i+1}}: {{r.lhs}} {{solvedData.rows[i].op}} {{r.rhs}}. Нарушение: {{r.violation}}.</p><p>Максимальное нарушение: {{result.error}}. Допуск: 10⁻⁹. Невязка не является гарантированной границей ошибки оптимума.</p></template></section>
</main>
<div v-if="projectDialog" class="modal-backdrop" @click.self="projectDialog=null"><section class="modal project-dialog" role="dialog" aria-modal="true" aria-labelledby="project-dialog-title"><button class="modal-close" @click="projectDialog=null" aria-label="Закрыть">×</button><p class="eyebrow">{{projectDialog.action==='create'?'НОВЫЙ ПРОЕКТ':'МОИ РЕШЕНИЯ'}}</p><template v-if="projectDialog.action==='delete'"><h2 id="project-dialog-title">Удалить проект?</h2><p>«{{projects.find(p=>p.id===projectDialog.id)?.name}}» и его расчёты будут удалены из истории.</p><div class="dialog-actions"><button class="secondary" @click="projectDialog=null">Отмена</button><button class="primary" @click="deleteProject">Удалить проект</button></div></template><form v-else @submit.prevent="submitProject"><h2 id="project-dialog-title">{{projectDialog.action==='create'?'Как назовём решение?':'Новое название.'}}</h2><label class="project-name-label" for="project-name">Название проекта</label><input ref="nameInput" id="project-name" class="project-name-input" v-model="projectName" placeholder="Например, Пример 1" maxlength="80" autocomplete="off"><p v-if="projectError" class="error" role="alert">{{projectError}}</p><div class="dialog-actions"><button type="button" class="secondary" @click="projectDialog=null">Отмена</button><button class="primary" type="submit">{{projectDialog.action==='create'?'Начать решение ↗':'Сохранить'}}</button></div></form></section></div>
<div v-if="showAbout" class="modal-backdrop" @click.self="showAbout=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="about-title"><button class="modal-close" @click="showAbout=false" aria-label="Закрыть">×</button><p class="eyebrow">МАТЕМАТИКА ЗА ИНТЕРФЕЙСОМ</p><h2 id="about-title">От базиса к оптимуму.</h2><p>Двухэтапный симплекс-метод. Сначала находим допустимый базис с искусственными переменными, затем оптимизируем исходную функцию.</p><p>Вычислительный алгоритм написан на Python и выполняется локально через WebAssembly. Данные не отправляются на сервер.</p><p>Графика на главной — иллюстрация в двух измерениях. Ваша задача решается по введённым коэффициентам.</p><button class="primary" @click="showAbout=false;start()">Начать решение ↗</button></section></div>
</div>
</template>
